INSERT OR IGNORE INTO settings(id,data) VALUES ('store','{"name":"homéy","tagline":"Simply Home.","currency":"PKR","email":"","whatsapp":"","instagram":"","facebook":"","announcement":"","heroTitle":"A home,\nwell composed.","heroText":"Linens to live with. Colours that belong. Discover a considered collection for the everyday.","heroImage":"/Images/catalogue/Home/bedsheets/1/IMG-20261031-WA0040.jpg","about":"Some homes are decorated. Others are composed. At homéy, we don’t design — we curate. We search for linens that feel wonderful to live with: soft, enduring and quietly luxurious. Towels, bedsheets and table linens in pastels, prints, and quiet neutrals — chosen with an eye that knows what belongs.","rayaAbout":"Raya atelier is a silver atelier where quiet luxury meets precious stones. We craft timeless silver adorned with real precious stones. Designed to catch the light and hold meaning.","checkoutEnabled":true,"shippingFee":300,"terms":"Product options, prices and delivery charges are shown before you place an order. Orders are subject to stock availability and confirmation by the store. Payment is made in advance by EasyPaisa transfer. Submit the order number, transfer reference and payment screenshot for manual review. Orders are dispatched after payment approval. Keep your order reference for enquiries. Please review the selected size, colour, quantity and delivery address before placing your order.","privacy":"We use the name, contact details and address submitted at checkout to process your order, arrange delivery and respond to enquiries. Your shopping bag is saved in your browser. Order information is stored in the store’s database and is accessible through the protected administration area. Payment screenshots are stored privately and reviewed by the store team. Order references let you return to submit evidence later. No card details are collected on this website.","shipping":"Delivery charges are shown in your shopping bag and at checkout. Delivery timing and service availability depend on your location and are confirmed when your order is accepted. Please provide a complete address and a phone number where you can be reached.","returns":"For a return or exchange enquiry, contact the store with your order reference and details of the item. Please retain the original packaging and keep the item unused while your enquiry is reviewed. Return eligibility and arrangements are confirmed by the store.","paymentMethod":"easypaisa_manual","easypaisaAccountName":"","easypaisaAccountNumber":"","paymentInstructions":"Transfer the exact order total to the EasyPaisa account shown here. Include your order number where possible, then submit the transaction reference and a clear screenshot."}');
